class Radio {
private:
    RF24 radio;
    FlightControl controls;
    unsigned long lastReceived;

public:
    Radio() : radio(PIN_RADIO_CE, PIN_RADIO_CSN), lastReceived(0) {}

    bool initialize() {
        if (!radio.begin()) {
            return false;
        }

        radio.setPALevel(RF24_PA_LOW);
        radio.setDataRate(RF24_250KBPS);
        radio.setChannel(RADIO_CHANNEL);
        radio.openReadingPipe(1, RADIO_ADDRESS);
        radio.startListening();

        return true;
    }

    bool update(FlightControl&amp; data) {
        if (radio.available()) {
            radio.read(&amp;controls, sizeof(FlightControl));
            lastReceived = millis();
            data = controls;
            return true;
        }

        // Failsafe después de 500ms sin señal
        if (millis() - lastReceived &gt; 500) {
            data.throttle = 0;
            data.roll = 0;
            data.pitch = 0;
            data.yaw = 0;
        }

        return false;
    }
};
