[Fuente 12V]
+12V ---&gt; Motor (+)
GND ----&gt; Motor (-)

Código Principal
void setup() {
    setupMotorControl();
    setupLEDs();
    loadPattern(heart);
}

void loop() {
    static uint8_t currentPosition = 0;

    if (currentRPM &gt;= TARGET_RPM * 0.95) {
        displayPattern(currentPosition);
        currentPosition = (currentPosition + 1) % DISPLAY_COLUMNS;
    }

    adjustMotorSpeed();
}
